(function() { const DarkModeConfig = { primaryBackground: '#121212', primaryText: '#e0e0e0', accentColor: '#bb86fc', secondaryBackground: '#2B2B2B', borderColor: '#444444', imageAdjustment: { brightness: 0.8, contrast: 1.2, saturation: 1.1 }, excludedSelectors: [ 'img[alt*="darkmode"]', 'picture[alt*="darkmode"]', 'video[alt*="darkmode"]', '.no-dark-mode', '.darkmode-exempt' ] }; function injectDarkMode() { const style = document.createElement('style'); style.id = 'dark-mode-styles'; style.innerHTML = ` body, html { background-color: ${DarkModeConfig.primaryBackground} !important; color: ${DarkModeConfig.primaryText} !important; } *:not(${DarkModeConfig.excludedSelectors.join(',')}) { background-color: ${DarkModeConfig.primaryBackground} !important; color: ${DarkModeConfig.primaryText} !important; border-color: ${DarkModeConfig.borderColor} !important; transition: background-color 0.2s ease, color 0.2s ease; } a, a:visited { color: ${DarkModeConfig.accentColor} !important; transition: color 0.2s ease; } a:hover, a:focus { color: ${DarkModeConfig.accentColor} !important; } button, input, select, textarea { background-color: ${DarkModeConfig.secondaryBackground} !important; color: ${DarkModeConfig.primaryText} !important; border: 1px solid ${DarkModeConfig.borderColor} !important; transition: background-color 0.2s ease; } button:hover, input:hover, select:hover { background-color: #444 !important; } img, picture, video { filter: brightness(${DarkModeConfig.imageAdjustment.brightness}) contrast(${DarkModeConfig.imageAdjustment.contrast}) saturate(${DarkModeConfig.imageAdjustment.saturation}) !important; transition: filter 0.2s ease; } ::-webkit-scrollbar { width: 12px; height: 12px; } ::-webkit-scrollbar-thumb { background-color: #444; border-radius: 10px; } ::-webkit-scrollbar-track { background-color: #222; } pre, code { background-color: ${DarkModeConfig.secondaryBackground} !important; color: ${DarkModeConfig.primaryText} !important; border-radius: 5px; padding: 5px; } ::selection { background-color: ${DarkModeConfig.accentColor}; color: #ffffff; } `; document.head.appendChild(style); } function toggleDarkMode(force = null) { const existingStyles = document.getElementById('dark-mode-styles'); if (force === null) { existingStyles ? existingStyles.remove() : injectDarkMode(); } else if (force === true && !existingStyles) { injectDarkMode(); } else if (force === false && existingStyles) { existingStyles.remove(); } } function initDarkMode() { const isDarkModeEnabled = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches; toggleDarkMode(isDarkModeEnabled); window.matchMedia('(prefers-color-scheme: dark)').addListener(e => { toggleDarkMode(e.matches); }); } window.toggleDarkMode = toggleDarkMode; initDarkMode(); })(); 